/**
 * Brute-Force-Angriff auf die Caesar-Verschlüsselung (Station 5.5).
 * rotiere und caesarEnt kennst du aus Projekt 11-5-1.
 * Suche (Strg + F) nach "TODO" und ergänze den Code.
 */
public class Bruteforce {

   /**
    * Verschiebt einen Großbuchstaben um rotationUm Stellen (nach Z geht es bei A weiter).
    */
   public char rotiere(char buchstabe, int rotationUm) {
      if (buchstabe < 'A' || buchstabe > 'Z') {   // ⓪ kein Großbuchstabe: unverändert
         return buchstabe;
      }
      rotationUm = rotationUm % 26;               // ① 26 Schritte sind einmal ganz herum
      int code = (int) buchstabe + rotationUm;    // ② ASCII-Code + Verschiebung
      if (code > 90) {                            // ③ hinter 'Z' (90)? vorne weiterzählen
         code = code - 26;
      }
      return (char) code;                         // ④ wieder als Zeichen
   }

   /**
    * Caesar-Entschlüsselung: um schluessel zurück = um 26 - schluessel vor.
    */
   public String caesarEnt(String geheimtext, int schluessel) {
      geheimtext = geheimtext.toUpperCase();
      String klartext = "";
      schluessel = schluessel % 26;
      for (int i = 0; i < geheimtext.length(); i++) {
         klartext = klartext + rotiere(geheimtext.charAt(i), 26 - schluessel);
      }
      return klartext;
   }

