public class BruteforceTest {

   @Test
   public void artikelGefunden() {
      Bruteforce bf = new Bruteforce();
      Assertions.assertTrue(bf.enthaeltArtikel("HALLODIEWELT"), "TODO 1: In HALLODIEWELT steckt DIE.");
      Assertions.assertTrue(bf.enthaeltArtikel("WODERFROSCH"), "TODO 1: In WODERFROSCH steckt DER.");
      Assertions.assertTrue(bf.enthaeltArtikel("DASHAUS"), "TODO 1: DASHAUS beginnt mit DAS (Position 0).");
   }

   @Test
   public void keinArtikel() {
      Bruteforce bf = new Bruteforce();
      Assertions.assertFalse(bf.enthaeltArtikel("HALLOWELT"), "TODO 1: In HALLOWELT steckt weder DER noch DIE noch DAS.");
   }

   @Test
   public void zaehleBeispiel() {
      Bruteforce bf = new Bruteforce();
      Assertions.assertEquals(2, bf.zaehle("BANANE", 'A'), "TODO 3: In BANANE kommt A zweimal vor.");
      Assertions.assertEquals(0, bf.zaehle("BANANE", 'X'), "TODO 3: In BANANE kommt X nicht vor.");
   }

   @Test
   public void haeufigsterBeispiel() {
      Bruteforce bf = new Bruteforce();
      Assertions.assertEquals('N', bf.haeufigsterBuchstabe("BANANEN"), "TODO 4: In BANANEN ist N am häufigsten.");
      Assertions.assertEquals('Z', bf.haeufigsterBuchstabe("ZZZ"), "TODO 4: In ZZZ ist Z am häufigsten.");
   }

   @Test
   public void schaetzeBeispiel() {
      Bruteforce bf = new Bruteforce();
      Assertions.assertEquals(3, bf.schaetzeSchluessel("HHHAB"), "TODO 4: H ist am häufigsten, H steht für E, also Schlüssel 3.");
   }
}
